<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Review;
use App\Domain\Review\Entity\ReviewSession;use App\Domain\Review\Enum\ReviewSessionKind;use App\Domain\Review\Enum\ReviewSessionStatus;use App\Domain\Review\Repository\ReviewSessionRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Review\Entity\ReviewSessionRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineReviewSessionRepository implements ReviewSessionRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em){} public function findActive(string $u,ReviewSessionKind $k):?ReviewSession{$r=$this->em->getRepository(ReviewSessionRecord::class)->findOneBy(['userId'=>$u,'kind'=>$k->value,'status'=>'ACTIVE'],['createdAt'=>'DESC']);return $r instanceof ReviewSessionRecord?$this->map($r):null;} public function findForUser(string $id,string $u):?ReviewSession{$r=$this->em->find(ReviewSessionRecord::class,$id);return $r instanceof ReviewSessionRecord&&$r->userId===$u?$this->map($r):null;} public function save(ReviewSession $s):void{$r=$this->em->find(ReviewSessionRecord::class,$s->id)??new ReviewSessionRecord();$r->id=$s->id;$r->userId=$s->userId;$r->kind=$s->kind->value;$r->status=$s->status->value;$r->requestedLimit=$s->requestedLimit;$r->createdAt=$s->createdAt;$r->completedAt=$s->completedAt;$this->em->persist($r);if($s->flashcardIds!==[]){$this->em->createQueryBuilder()->delete(ReviewSessionCardRecord::class,'c')->where('c.sessionId=:id')->setParameter('id',$s->id)->getQuery()->execute();foreach($s->flashcardIds as $position=>$cardId){$card=new ReviewSessionCardRecord();$card->sessionId=$s->id;$card->flashcardId=$cardId;$card->position=$position+1;$this->em->persist($card);}}} private function map(ReviewSessionRecord $r):ReviewSession{$cards=$this->em->getRepository(ReviewSessionCardRecord::class)->findBy(['sessionId'=>$r->id],['position'=>'ASC']);return new ReviewSession($r->id,$r->userId,ReviewSessionKind::from($r->kind),ReviewSessionStatus::from($r->status),$r->requestedLimit,$r->createdAt,$r->completedAt,array_map(static fn(ReviewSessionCardRecord $card)=>$card->flashcardId,$cards));} }
